require __DIR__.'/app/bootstrap.php';$ctx=growth_seller_context();$u=$ctx['user'];$owner=(int)$ctx['owner_id'];$businesses=growth_owned_businesses($owner);$businessIds=array_map(fn($b)=>(int)$b['id'],$businesses);$msg=$err=null;$tab=in_array($_GET['tab']??'leads',['leads','bookings','reviews','verification','coupons','menu','staff','services','analytics'],true)?$_GET['tab']:'leads';$tabPerm=['leads'=>'leads','bookings'=>'bookings','reviews'=>'reviews','verification'=>'verification','coupons'=>'coupons','menu'=>'menu','services'=>'services','analytics'=>'analytics'];if($ctx['is_staff']){if($tab==='staff'){http_response_code(403);exit('Only the business owner can manage seller staff.');}$need=$tabPerm[$tab]??'';if($need!==''&&!growth_seller_can($ctx,$need)){http_response_code(403);exit('This seller-staff account does not have permission for this Growth CRM section.');}}
function sg_business_ok(int $id,array $ids): void {if(!$id||!in_array($id,$ids,true))throw new RuntimeException('Invalid business selection.');}
if($_SERVER['REQUEST_METHOD']==='POST')try{csrf_check();$action=(string)($_POST['action']??'');$bid=(int)($_POST['business_id']??0);if($bid)sg_business_ok($bid,$businessIds);
 if($action==='lead'){if(!growth_seller_can($ctx,'leads'))throw new RuntimeException('Staff permission denied.');$st=in_array($_POST['status']??'contacted',['new','contacted','qualified','won','lost','spam'],true)?$_POST['status']:'contacted';db()->prepare("UPDATE business_leads l JOIN businesses b ON b.id=l.business_id SET l.status=?,l.estimated_value=? WHERE l.id=? AND b.owner_id=?")->execute([$st,max(0,(float)$_POST['estimated_value']),(int)$_POST['id'],$owner]);$msg='Lead updated.';
 }elseif($action==='booking'){if(!growth_seller_can($ctx,'bookings'))throw new RuntimeException('Staff permission denied.');$st=in_array($_POST['status']??'confirmed',['pending','confirmed','completed','cancelled','no_show'],true)?$_POST['status']:'confirmed';db()->prepare("UPDATE business_bookings bk JOIN businesses b ON b.id=bk.business_id SET bk.status=? WHERE bk.id=? AND b.owner_id=?")->execute([$st,(int)$_POST['id'],$owner]);$msg='Booking updated.';
 }elseif($action==='reply_review'){if(!growth_seller_can($ctx,'reviews'))throw new RuntimeException('Staff permission denied.');growth_reply_review((int)$_POST['id'],$owner,trim((string)$_POST['reply']));$msg='Review reply saved.';
 }elseif($action==='verification'){if(!growth_seller_can($ctx,'verification'))throw new RuntimeException('Staff permission denied.');if(!growth_entitled($owner,'verification',true))throw new RuntimeException('Verification is not included in your subscription.');growth_request_verification($bid,$owner,(string)$_POST['verification_type'],trim((string)$_POST['notes']));$msg='Verification request submitted.';
 }elseif($action==='coupon'){if(!growth_seller_can($ctx,'coupons'))throw new RuntimeException('Staff permission denied.');if(!growth_enabled('coupons_enabled',true))throw new RuntimeException('Coupons disabled.');$code=strtoupper(preg_replace('/[^A-Z0-9]/i','',trim((string)$_POST['code'])));if(!$code)throw new RuntimeException('Coupon code required.');db()->prepare("INSERT INTO business_coupons(business_id,title,code,discount_type,discount_value,min_spend,max_redemptions,per_user_limit,starts_at,ends_at,status) VALUES(?,?,?,?,?,?,?,?,?,?,'active') ON DUPLICATE KEY UPDATE title=VALUES(title),discount_type=VALUES(discount_type),discount_value=VALUES(discount_value),min_spend=VALUES(min_spend),max_redemptions=VALUES(max_redemptions),per_user_limit=VALUES(per_user_limit),starts_at=VALUES(starts_at),ends_at=VALUES(ends_at),status='active'")->execute([$bid,trim((string)$_POST['title']),$code,in_array($_POST['discount_type']??'percent',['percent','fixed'],true)?$_POST['discount_type']:'percent',max(0,(float)$_POST['discount_value']),max(0,(float)$_POST['min_spend']),max(0,(int)$_POST['max_redemptions']),max(1,(int)$_POST['per_user_limit']),trim((string)$_POST['starts_at'])?:null,trim((string)$_POST['ends_at'])?:null]);$msg='Coupon saved.';
 }elseif($action==='menu'){if(!growth_seller_can($ctx,'menu')||!growth_entitled($owner,'restaurant_menu',true))throw new RuntimeException('Menu permission/subscription denied.');$title=trim((string)($_POST['menu_title']??'Main Menu'))?:'Main Menu';db()->prepare("INSERT INTO restaurant_menus(business_id,title,status) VALUES(?,?,1) ON DUPLICATE KEY UPDATE status=1")->execute([$bid,$title]);$menu=(int)growth_scalar("SELECT id FROM restaurant_menus WHERE business_id=? AND title=?",[$bid,$title]);db()->prepare("INSERT INTO restaurant_menu_items(menu_id,category_name,name,description,price,image_url,available,sort_order) VALUES(?,?,?,?,?,?,1,?)")->execute([$menu,trim((string)$_POST['category_name'])?:null,trim((string)$_POST['name']),trim((string)$_POST['description'])?:null,max(0,(float)$_POST['price']),trim((string)$_POST['image_url'])?:null,max(1,(int)($_POST['sort_order']??10))]);$msg='Menu item added.';
 }elseif($action==='staff'){if($ctx['is_staff'])throw new RuntimeException('Only business owner can assign staff.');if(!growth_entitled($owner,'seller_staff',true))throw new RuntimeException('Seller staff is not included in your subscription.');$email=strtolower(trim((string)$_POST['email']));$staff=growth_row("SELECT id FROM users WHERE email=? AND status='active' LIMIT 1",[$email]);if(!$staff)throw new RuntimeException('Create the staff user account first, then enter its email.');$sid=(int)$staff['id'];if($sid===$owner)throw new RuntimeException('Owner cannot be assigned as staff.');$perms=array_values(array_intersect(['products','orders','bookings','leads','reviews','verification','coupons','menu','analytics','auctions','services','inventory','finance'],(array)($_POST['permissions']??[])));db()->prepare("INSERT INTO seller_staff(owner_user_id,staff_user_id,permissions_json,status) VALUES(?,?,?,1) ON DUPLICATE KEY UPDATE permissions_json=VALUES(permissions_json),status=1")->execute([$owner,$sid,json_encode($perms)]);$msg='Seller staff assigned.';
 }elseif($action==='quote'){if(!growth_seller_can($ctx,'services')||!growth_entitled($owner,'service_quotes',true))throw new RuntimeException('Service quote permission/subscription denied.');$req=(int)$_POST['request_id'];db()->prepare("INSERT INTO service_quotes(request_id,business_id,seller_user_id,amount,message,status) VALUES(?,?,?,?,?,'sent') ON DUPLICATE KEY UPDATE amount=VALUES(amount),message=VALUES(message),status='sent'")->execute([$req,$bid,$owner,max(0,(float)$_POST['amount']),trim((string)$_POST['message'])?:null]);$msg='Service quote sent.';
 }
}catch(Throwable $e){$err=$e->getMessage();}
$leadRows=growth_rows("SELECT l.*,b.name business_name FROM business_leads l JOIN businesses b ON b.id=l.business_id WHERE b.owner_id=? ORDER BY FIELD(l.status,'new','contacted','qualified','won','lost','spam'),l.id DESC LIMIT 150",[$owner]);$bookingRows=growth_rows("SELECT bk.*,b.name business_name FROM business_bookings bk JOIN businesses b ON b.id=bk.business_id WHERE b.owner_id=? ORDER BY bk.booking_date DESC,bk.booking_time DESC LIMIT 150",[$owner]);$reviewRows=growth_rows("SELECT r.*,b.name business_name,u.name customer_name FROM business_reviews r JOIN businesses b ON b.id=r.business_id JOIN users u ON u.id=r.user_id WHERE b.owner_id=? AND r.status='published' ORDER BY r.id DESC LIMIT 150",[$owner]);$verificationRows=growth_rows("SELECT v.*,b.name business_name FROM business_verifications v JOIN businesses b ON b.id=v.business_id WHERE b.owner_id=? ORDER BY v.id DESC LIMIT 100",[$owner]);$coupons=growth_rows("SELECT c.*,b.name business_name FROM business_coupons c JOIN businesses b ON b.id=c.business_id WHERE b.owner_id=? ORDER BY c.id DESC LIMIT 100",[$owner]);$menus=growth_rows("SELECT mi.*,m.title menu_title,b.name business_name FROM restaurant_menu_items mi JOIN restaurant_menus m ON m.id=mi.menu_id JOIN businesses b ON b.id=m.business_id WHERE b.owner_id=? ORDER BY b.name,mi.id DESC LIMIT 150",[$owner]);$staff=growth_rows("SELECT ss.*,u.name,u.email FROM seller_staff ss JOIN users u ON u.id=ss.staff_user_id WHERE ss.owner_user_id=? ORDER BY ss.id DESC",[$owner]);$serviceRequests=growth_service_requests(null,50);$ana=growth_analytics_summary($businessIds[0]??null,30);
